export function companyKycOutboundCompactDisposableUrl(environment={}){
 // The separately owned local QA server uses 6550. Preserve every historical
 // target restriction by validating its otherwise identical URL at 6549.
 let target;try{target=new URL(environment.CUTOVER_TEST_DATABASE_URL);}catch{return companyKycRejectionFeedbackDisposableUrl(environment);}
 if(target.port!=='6550')return companyKycRejectionFeedbackDisposableUrl(environment);
 const historicalTarget=new URL(target);historicalTarget.port='6549';
 companyKycRejectionFeedbackDisposableUrl({...environment,CUTOVER_TEST_DATABASE_URL:historicalTarget.toString()});
 return target;
}
